// RainManager.cs is generated by Gemini

using UnityEngine;
using UnityEngine.SceneManagement; // Required to restart the scene

public class RainManager : MonoBehaviour
{
    [Header("Phase Timers")]
    [Tooltip("Seconds before the rain actually starts")]
    public float prepTime = 60f; 
    private float currentTimer = 0f;
    public bool isRaining = false;

    [Header("Water Objects & Limits")]
    public Transform waterCube;
    [Tooltip("Y position where water is hidden below the street")]
    public float minWaterY = -0.5f;   
    [Tooltip("Y position that triggers Game Over")]
    public float maxWaterY = 2.0f;    
    [Tooltip("Base speed the water moves. Adjust this to balance the game.")]
    public float baseWaterSpeed = 0.1f; 

    [Header("Drainages")]
    [Tooltip("Drag all 4 of your drainages here")]
    public DrainageNode[] drainages;

    void Start()
    {
        // Start the game with the water hidden below the street
        Vector3 startPos = waterCube.position;
        startPos.y = minWaterY;
        waterCube.position = startPos;
    }

    void Update()
    {
        // 1. Handle Prep Phase
        if (!isRaining)
        {
            currentTimer += Time.deltaTime;
            if (currentTimer >= prepTime)
            {
                isRaining = true;
                Debug.Log("Prep time over! Rain has started.");
            }
            return; // Stop running the rest of the code until it rains
        }

        // 2. Calculate Total Debris across all 4 drainages
        int totalDebris = 0;
        foreach (DrainageNode node in drainages)
        {
            if (node != null)
            {
                totalDebris += node.obstacleLevel;
            }
        }

        // 3. Move the Water
        // The math exactly matches your logic: 
        // 20 = +10 (fast rise), 11 = +1 (slow rise), 10 = 0 (stable), 0 = -10 (fast drain)
        float flowRate = (totalDebris - 10f) * baseWaterSpeed;
        
        Vector3 newPos = waterCube.position;
        newPos.y += flowRate * Time.deltaTime;

        // Clamp the water so it never goes below the minimum hidden level
        newPos.y = Mathf.Max(newPos.y, minWaterY);
        waterCube.position = newPos;

        // 4. Check for Game Over
        if (waterCube.position.y >= maxWaterY)
        {
            GameOver();
        }
    }

    void GameOver()
    {
        Debug.Log("Game Over! Restarting Scene...");
        // Loads the currently active scene again to instantly restart
        SceneManager.LoadScene(SceneManager.GetActiveScene().name);
    }
}